using System;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class BeamDeflectionSummary {
 public string GeometrySource="",ResultSource="",GeometryUnit="",DisplacementUnit="",Vertical="Y",Criteria="";public bool ZUp,ServiceBasis,SupportsVerified;public int Nodes,Members;public List<string> Cases=new List<string>();
}
static class BeamDeflectionReport {
 static string F(double v,int d){return v.ToString("F"+d,CultureInfo.InvariantCulture);}
 static string Result(BeamDeflectionResult r){return r.Exceeds?"EXCEEDS":r.Qualified?"OK":r.Status.StartsWith("NOT CHECKED")?"NOT CHECKED":"REVIEW";}
 internal static readonly string[] SummaryHeaders={"Beam","Members","Supports A-B","Span type","L m","Load case","Max |δrel| mm","At x m (node)","δallow mm","L/δ","δ/δallow","Result"};
 internal static string[] SummaryRow(BeamDeflectionResult r){return new[]{r.Beam,r.Members,r.StartNode+" - "+r.EndNode,r.SpanType==BeamDeflection.Cantilever?"Cantilever":"Between supports",F(r.Span,3),r.Case,F(r.MaximumMm,2),F(r.At,3)+" ("+r.GoverningNode+")",F(r.LimitMm,2),r.Ratio,F(r.Utilization,2),Result(r)};}
 internal static readonly string[] ReportHeaders={"Beam","Members","Span L m","Load case","Max δrel mm","Node","δallow mm","L/δ","Result"};
 internal static string[] ReportRow(BeamDeflectionResult r){return new[]{r.Beam,r.Members,F(r.Span,3)+(r.SpanType==BeamDeflection.Cantilever?" (cantilever)":""),r.Case,F(r.MaximumMm,2),r.GoverningNode.ToString(CultureInfo.InvariantCulture),F(r.LimitMm,2),r.Ratio,Result(r)+" ("+F(r.Utilization,2)+")"};}
 internal static string Text(BeamDeflectionSummary s,List<BeamDeflectionResult> results){var b=new StringBuilder();b.AppendLine("BEAM DEFLECTION CHECK FROM STAAD.Pro RESULTS");b.AppendLine("Displacement relative to the displaced support chord, per physical beam and load case.");b.AppendLine("Between supports: δrel(x) = u(x) - [uA + (uB - uA)·x/L]. Cantilever: δrel(x) = u(x) - uA. δallow = L/n (or the smaller absolute limit).");b.AppendLine("Geometry: "+s.GeometrySource+"; unit "+s.GeometryUnit+"; "+s.Nodes+" nodes; "+s.Members+" members.");b.AppendLine("Displacements: "+s.ResultSource+"; unit "+s.DisplacementUnit+"; global "+s.Vertical+" component; load cases "+string.Join(", ",s.Cases)+".");b.AppendLine();b.AppendLine(string.Join(" | ",SummaryHeaders));foreach(var r in results)b.AppendLine(string.Join(" | ",SummaryRow(r)));b.AppendLine();
  foreach(var r in results){b.AppendLine(r.Beam+" / load case "+r.Case+": "+r.Status);b.AppendLine("Node | x m | u mm | chord mm | δrel mm");foreach(var st in r.Stations)b.AppendLine(st.Node+" | "+F(st.Station,3)+" | "+F(st.Absolute,3)+" | "+F(st.Chord,3)+" | "+F(st.Relative,3));b.AppendLine();}
  b.AppendLine("Deflections are checked at STAAD analysis nodes only. Maxima between nodes are not captured; add intermediate nodes in STAAD where needed. This record does not constitute engineer approval.");return b.ToString();}
 internal static EngineeringReport Create(BeamDeflectionSummary s,List<BeamDeflectionResult> results){var project=ProjectInfoStore.Read();var report=ProfessionalReport.Create("Beam Deflection Check",project.Name,project.Location,project.Office);report.Subtitle="Serviceability deflection of physical beams from STAAD.Pro node coordinates and node displacements";
  int exceed=results.Count(r=>r.Exceeds),review=results.Count(r=>!r.Exceeds&&!r.Qualified);var governing=results.OrderByDescending(r=>r.Utilization).FirstOrDefault();
  report.Highlights.Add(new KeyValuePair<string,string>("Checks",results.Count.ToString(CultureInfo.InvariantCulture)));report.Highlights.Add(new KeyValuePair<string,string>("Exceeding limit",exceed.ToString(CultureInfo.InvariantCulture)));report.Highlights.Add(new KeyValuePair<string,string>("Needs review",review.ToString(CultureInfo.InvariantCulture)));if(governing!=null)report.Highlights.Add(new KeyValuePair<string,string>("Governing δ/δallow",F(governing.Utilization,2)+" ("+governing.Beam+", LC "+governing.Case+")"));
  var scope=report.Section("Scope and method");
  scope.Paragraph("This record checks the serviceability deflection of straight physical beams modelled in STAAD.Pro. A physical beam may consist of several analysis members joined at intermediate nodes; those intermediate nodes are deflection stations, not supports. Each beam is checked for each selected load case using the global translation component normal to the beam axis.");
  scope.Equation("Between supports:  δrel(x) = u(x) − [uA + (uB − uA)·x / L]");scope.Equation("Cantilever (fixed at A):  δrel(x) = u(x) − uA");scope.Equation("δallow = L / n   (or the absolute limit if smaller);   check  max|δrel| ≤ δallow");
  scope.Paragraph("u(x) is the STAAD node translation, uA and uB are the translations of Support A and Support B, x is the distance from Support A along the beam and L is the support-to-support span (cantilever length for cantilevers). Subtracting the support chord removes rigid-body movement from support settlement or column shortening, so the result is the member's own bending deflection.");
  var input=report.Section("STAAD input data");
  input.Table(new[]{"Item","Value"},new[]{
   new[]{"Geometry source",s.GeometrySource==""?"Pasted / typed tables":s.GeometrySource},new[]{"Geometry unit",s.GeometryUnit},new[]{"Nodes / members read",s.Nodes+" / "+s.Members},
   new[]{"Displacement source",s.ResultSource==""?"Pasted / typed table":s.ResultSource},new[]{"Displacement unit",s.DisplacementUnit},
   new[]{"Deflection component","Global "+s.Vertical+(s.ZUp?" (model uses SET Z UP)":"")},new[]{"Load cases available",string.Join(", ",s.Cases)},
   new[]{"Service (unfactored) load basis confirmed",s.ServiceBasis?"Yes":"No - results marked REVIEW"},new[]{"Support nodes confirmed",s.SupportsVerified?"Yes":"No - results marked REVIEW"}});
  input.Note("STAAD data required: (1) node coordinates, (2) member incidences, (3) node translations for every node on each checked beam, including both supports and all intermediate nodes, for the service load cases. Units are taken from the table headings or STAAD UNIT command when present; otherwise the selected unit is used.");
  var criteria=report.Section("Deflection criteria");criteria.Paragraph("Criterion applied: "+s.Criteria+". Limits are entered per beam as L/n with an optional absolute limit in millimetres.");
  criteria.Table(new[]{"Typical limit","Application (NSCP 2015 Table 424.2.2 for reinforced concrete)"},new[]{new[]{"L/180","Flat roofs not supporting or attached to nonstructural elements likely to be damaged - immediate live-load deflection"},new[]{"L/360","Floors not supporting or attached to nonstructural elements likely to be damaged - immediate live-load deflection"},new[]{"L/480","Roof or floor supporting or attached to nonstructural elements likely to be damaged - deflection after attachment"},new[]{"L/240","Roof or floor supporting or attached to nonstructural elements not likely to be damaged - deflection after attachment"}});
  criteria.Note("STAAD linear-elastic results use the modelled section stiffness. For reinforced concrete, cracking and long-term (creep/shrinkage) effects required by NSCP 2015 Section 424.2.3 are included only if the STAAD model accounts for them. Steel and other members use the limit specified by the project or governing code.");
  var summary=report.Section("Summary of checks");summary.Table(ReportHeaders,results.Select(ReportRow));
  summary.Note("OK = within the limit at every analysis node with load basis and supports confirmed. REVIEW = within the limit but a confirmation is still pending. NOT CHECKED = no intermediate node between the supports. EXCEEDS = the limit is exceeded.");
  foreach(var group in results.GroupBy(r=>r.Beam+"\u0001"+r.Members)){var first=group.First();var section=report.Section("Beam "+first.Beam+" - members "+first.Members);section.NewPage=false;
   section.Paragraph("Supports: node "+first.StartNode+" (A) to node "+first.EndNode+" (B). "+(first.SpanType==BeamDeflection.Cantilever?"Cantilever length":"Span")+" L = "+F(first.Span,3)+" m with "+(first.Stations.Count-2)+" intermediate node(s); largest node spacing "+F(first.LargestSegment,3)+" m. Limit L/"+F(first.LimitRatio,0)+(first.AbsoluteLimitMm>0?" or "+F(first.AbsoluteLimitMm,1)+" mm":"")+" = "+F(first.LimitMm,2)+" mm.");
   foreach(var r in group){section.Table(new[]{"Node","x m","u mm (STAAD)","Chord mm","δrel mm"},r.Stations.Select(st=>new[]{st.Node.ToString(CultureInfo.InvariantCulture),F(st.Station,3),F(st.Absolute,3),F(st.Chord,3),F(st.Relative,3)}));
    var g=r.Stations.First(st=>st.Node==r.GoverningNode);
    section.Equation("Load case "+r.Case+", governing node "+g.Node+" at x = "+F(g.Station,3)+" m:  δrel = "+F(g.Absolute,3)+" − ("+F(g.Chord,3)+") = "+F(g.Relative,3)+" mm;  |δrel| = "+F(r.MaximumMm,2)+" mm vs δallow = "+F(r.LimitMm,2)+" mm  →  "+r.Ratio+",  δ/δallow = "+F(r.Utilization,2));
    section.Note(r.Status);section.Figure(Svg(r),"Deflected shape relative to the support chord - "+r.Beam+", load case "+r.Case+" (vertical scale exaggerated)",true);}}
  var limits=report.Section("Limitations and review notes");
  limits.Paragraph("Deflections are evaluated at STAAD analysis nodes only. A maximum between nodes is not captured; where the largest node spacing is a significant part of the span, add intermediate nodes in STAAD (for example at quarter or tenth points) and re-run the analysis.");
  limits.Paragraph("The check depends on the STAAD model, member releases, section properties, load cases and units supplied. Confirm that the selected cases are service (unfactored) loads and that Support A and Support B are the real supports of each beam.");
  limits.Paragraph("This calculation record is generated from the imported data. It is not an engineer's approval or signature and should be reviewed before issue.");
  return report;}
 internal static string Svg(BeamDeflectionResult r){double w=760,h=210,left=50,right=30,mid=96;double scaleX=(w-left-right)/Math.Max(r.Span,1e-9);double peak=Math.Max(r.Stations.Max(s=>Math.Abs(s.Relative)),Math.Max(r.LimitMm,1e-6));double scaleY=70/peak;Func<double,double> X=x=>left+x*scaleX;Func<double,double> Y=v=>mid-v*scaleY;var b=new StringBuilder();
  b.Append("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 "+F(w,0)+" "+F(h,0)+"' width='100%' font-family='Arial' font-size='11'>");
  b.Append("<rect x='"+F(left,1)+"' y='"+F(Y(r.LimitMm),1)+"' width='"+F(w-left-right,1)+"' height='"+F(2*r.LimitMm*scaleY,1)+"' fill='#e8f3f1'/>");
  b.Append("<line x1='"+F(left,1)+"' y1='"+F(mid,1)+"' x2='"+F(w-right,1)+"' y2='"+F(mid,1)+"' stroke='#7b8794' stroke-width='1.5'/>");
  b.Append("<polyline fill='none' stroke='"+(r.Exceeds?"#b42318":"#0f6e6e")+"' stroke-width='2.2' points='"+string.Join(" ",r.Stations.Select(s=>F(X(s.Station),1)+","+F(Y(s.Relative),1)))+"'/>");
  foreach(var s in r.Stations){b.Append("<circle cx='"+F(X(s.Station),1)+"' cy='"+F(Y(s.Relative),1)+"' r='3' fill='#213b57'/>");b.Append("<text x='"+F(X(s.Station),1)+"' y='"+F(h-40,1)+"' text-anchor='middle' fill='#526174'>"+s.Node+"</text>");}
  bool cant=r.SpanType==BeamDeflection.Cantilever;b.Append("<path d='M"+F(left,1)+" "+F(mid,1)+" l-9 16 h18 z' fill='#213b57'/>");if(!cant)b.Append("<path d='M"+F(w-right,1)+" "+F(mid,1)+" l-9 16 h18 z' fill='#213b57'/>");else b.Append("<rect x='"+F(left-14,1)+"' y='"+F(mid-26,1)+"' width='6' height='52' fill='#213b57'/>");
  var g=r.Stations.First(s=>s.Node==r.GoverningNode);b.Append("<text x='"+F(Math.Min(w-150,Math.Max(left+5,X(g.Station)+6)),1)+"' y='"+F(Y(g.Relative)+(g.Relative<0?16:-8),1)+"' fill='#202d3c' font-weight='bold'>"+F(g.Relative,2)+" mm</text>");
  b.Append("<text x='"+F(left,1)+"' y='"+F(h-14,1)+"' fill='#526174'>A (node "+r.StartNode+")   x →   L = "+F(r.Span,3)+" m   shaded band = ±δallow "+F(r.LimitMm,2)+" mm   node numbers shown below the beam</text>");
  b.Append("<text x='"+F(w-right,1)+"' y='"+F(h-14,1)+"' text-anchor='end' fill='#526174'>"+(cant?"free end":"B (node "+r.EndNode+")")+"</text></svg>");return b.ToString();}
 // Drawn PDF/print pages for the deflected shapes; the numbered tables come from the engineering report pages.
 internal static void AddShapeSheets(CalculationDocument document,List<BeamDeflectionResult> results){for(int i=0;i<results.Count;i+=3){var page=results.Skip(i).Take(3).ToList();document.Sheets.Add(g=>{PdfBrand.Draw(g);CalculationDocument.Section(g,"DEFLECTED SHAPES RELATIVE TO SUPPORT CHORD",40);float top=80;foreach(var r in page){Shape(g,r,36,top,523,230);top+=245;}});}}
 static void Shape(Graphics g,BeamDeflectionResult r,float x0,float y0,float width,float height){CalculationDocument.Text(g,r.Beam+" - load case "+r.Case+"  |  L = "+F(r.Span,3)+" m  |  max |δrel| = "+F(r.MaximumMm,2)+" mm at node "+r.GoverningNode+"  |  δallow = "+F(r.LimitMm,2)+" mm  |  "+Result(r),x0,y0,width,30,8,true);
  float left=x0+24,right=x0+width-16,mid=y0+105;float scaleX=(float)((right-left)/Math.Max(r.Span,1e-9));double peak=Math.Max(r.Stations.Max(s=>Math.Abs(s.Relative)),Math.Max(r.LimitMm,1e-6));float scaleY=(float)(60/peak);
  using(var band=new SolidBrush(Color.FromArgb(232,243,241)))g.FillRectangle(band,left,mid-(float)r.LimitMm*scaleY,right-left,(float)(2*r.LimitMm*scaleY));
  using(var axis=new Pen(Color.FromArgb(123,135,148),1f))g.DrawLine(axis,left,mid,right,mid);
  var points=r.Stations.Select(s=>new PointF(left+(float)s.Station*scaleX,mid-(float)s.Relative*scaleY)).ToArray();using(var pen=new Pen(r.Exceeds?Color.FromArgb(180,35,24):Color.FromArgb(15,110,110),1.8f))if(points.Length>1)g.DrawLines(pen,points);
  using(var dot=new SolidBrush(Color.FromArgb(33,59,87))){foreach(var p in points)g.FillEllipse(dot,p.X-2.2f,p.Y-2.2f,4.4f,4.4f);g.FillPolygon(dot,new[]{new PointF(left,mid),new PointF(left-7,mid+12),new PointF(left+7,mid+12)});if(r.SpanType!=BeamDeflection.Cantilever)g.FillPolygon(dot,new[]{new PointF(right,mid),new PointF(right-7,mid+12),new PointF(right+7,mid+12)});}
  for(int i=0;i<r.Stations.Count;i++)if(r.Stations.Count<=24||i%Math.Max(1,r.Stations.Count/12)==0||i==r.Stations.Count-1)CalculationDocument.Text(g,r.Stations[i].Node.ToString(CultureInfo.InvariantCulture),points[i].X-14,mid+70,28,14,7);
  CalculationDocument.Text(g,"Node numbers along the beam; shaded band = ±δallow; vertical scale exaggerated.",x0,y0+height-24,width,14,7);}
}
}
